const ingredients = items;

// 1. Handle Empty Inventory
if (!ingredients || ingredients.length === 0) {
  return {
    formattedList: "📝 *Ingredient List*\n\nYour inventory is currently empty. Switch to Ingredient mode and type `bought...` to add items!"
  };
}

// 2. Build the Header
let message = "📝 *Current Inventory Stock*\n";
message += "━━━━━━━━━━━━━━━\n\n";

// 3. Loop through and format each row
ingredients.forEach(item => {
  const data = item.json;
  const name = data.ingredient_name;
  const qty = parseFloat(data.current_quantity).toFixed(2);
  const unit = data.unit_name;
  const cost = parseFloat(data.current_cost).toFixed(2);

  // Add a status emoji based on stock levels
  let statusEmoji = "✅";
  if (qty <= 0) {
    statusEmoji = "❌"; // Out of stock
  } else if (qty < 5) {
    statusEmoji = "⚠️"; // Low stock warning
  }

  message += `${statusEmoji} *${name}*\n`;
  message += `     Stock: ${qty} ${unit}\n`;
  message += `     Avg Cost: $${cost} / ${unit}\n\n`;
});

message += "━━━━━━━━━━━━━━━\n";
message += `_Total unique items: ${ingredients.length}_`;

return {
  formattedList: message,
  chat_id:$('ParseFirstInput').first().json.telegram.message.chat.id
};

