const queryResults = $input.first().json;
const userInput = $('Switch1').first().json.data;
const chatId = $('ParseFirstInput').first().json.telegram.message.chat.id;

let success = true;
let errorMessage = "";
let decreaseAmount = parseFloat(userInput.quantity);
let newQuantity;

// --- 1. Validation Logic ---

if (!queryResults.from_unit_name) {
  success = false;
  errorMessage = `⚠️ *Invalid Unit*\n\nI don't recognize the unit "**${userInput.unit}**". Please check your spelling or use a standard unit like kg, g, or L.`;
} 
else if (queryResults.from_unit_name !== queryResults.to_unit_name && !queryResults.multiplier) {
  success = false;
  errorMessage = `❓ *Conversion Missing*\n\nI don't know how to convert **${queryResults.from_unit_name}** to the base unit (**${queryResults.to_unit_name}**) for ${queryResults.ingredient_name}.`;
} 
else {
  // Calculate conversion if needed
  if (queryResults.from_unit_name !== queryResults.to_unit_name) {
    decreaseAmount = decreaseAmount * queryResults.multiplier;
  }

  // Check stock levels
  if (queryResults.current_quantity < decreaseAmount) {
    success = false;
    errorMessage = `⚠️ *Insufficient Stock*\n\nIngredient: *${queryResults.ingredient_name}*\nRequested: ${decreaseAmount}${queryResults.to_unit_name}\nAvailable: ${queryResults.current_quantity}${queryResults.to_unit_name}\n\n_Please restock before recording this usage._`;
  } else {
    newQuantity = queryResults.current_quantity - decreaseAmount;
  }
}

// --- 2. Return Logic ---

if (success) {
  return {
    success: true,
    chat_id: chatId,
    ingredient_name: queryResults.ingredient_name,
    newQuantity: newQuantity,
    usedAmount: decreaseAmount,
    unit: queryResults.to_unit_name
  };
} else {
  return {
    success: false,
    chat_id: chatId,
    message: errorMessage // This is the nice message to send to Telegram
  };
}

